import{z as r,x as s,o as t,c as p,q as n,j as B,D as a,d as A,s as i,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const k=JSON.parse('{"title":"特征级草稿：Eagle 一族","description":"","frontmatter":{"title":"特征级草稿：Eagle 一族","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/spec-eagle-family.md","filePath":"llm/spec-eagle-family.md","lastUpdated":1791063341000}'),d={name:"llm/spec-eagle-family.md"};function m(D,E,c,f,h,g){const l=s("Mermaid");return t(),p("div",null,[E[2]||(E[2]=n('<h1 id="特征级草稿-eagle-一族" tabindex="-1">特征级草稿：Eagle 一族 <a class="header-anchor" href="#特征级草稿-eagle-一族" aria-label="Permalink to &quot;特征级草稿：Eagle 一族&quot;">​</a></h1><div class="epigraph"><p>特征序列本身是因果的——既然如此，草稿就该在特征上自回归，而不是在一份已经过期的隐状态上盲猜。</p><footer>—— 据 Li et al., EAGLE, ICML 2024 的 feature uncertainty 口径整理</footer></div><p><a href="/llm/spec-self-draft-medusa">上一课</a>把多 token 头挂在同一份隐状态上，缺口已在结尾点破：\\(h_t\\) 对下一词充分、对更远位置不充分，远位对齐只能靠树碰。<a href="/llm/eagle">EAGLE</a> 一族把草稿搬进特征层：让一个轻量草稿模块在目标模型的特征序列上自回归地走，每走一步都基于「刚被目标确认过的特征」。本课写这一族怎么解决特征歧义、怎么从静态树长到动态树、EAGLE-3 又为什么敢扔掉特征回归。验证的代数与树掩码语义不重讲。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>特征级草稿有一个原生的坑：同一份特征对应的下一词分布是宽的，采样落到的具体 token 却只有一个。草稿若只看特征，它 condition 在「分布」上；目标实际生成的却是从分布里抽出的那个词。这个错位就是 Li 等人说的 feature uncertainty：特征决定不了 token，token 却决定下一步的特征。不同 token 从同一特征出发走出完全不同的后续，草稿在这一步就开始猜歧义。</p><p>第二个问题是训练定位：草稿该学什么？独立小模型从 token 重新学起太浪费；直接回归目标特征又把草稿的容量按在「模仿倒二层」上。谱系三代的分野恰好在这两个问题的答案上。</p><p><span class="marginnote">直觉类比：\\(h_t\\) 像天气预报「明天降水概率 70%」，token 是明天真实下没下雨。草稿若只看预报，手里只是个模糊判断；把今天已经落定的真实天气（错拍 token 嵌入）也递给它，它才能顺着已实现的那条路去猜下一步。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>EAGLE</strong>：草稿 = 一层解码器 + 冻结的目标 LM 头。输入两路：目标模型倒数第二层的特征序列，以及错开一拍的已采样 token 嵌入——把「分布上抽出的词」显式喂给草稿，歧义在这一步解开。草稿先预测下一步特征，再过冻结词头变成 token 分布。验证沿用树注意力加拒绝采样，声明无损。树是静态的。</p><p><strong>EAGLE-2</strong>：树改成动态生长。用草稿 softmax 置信度当接受率的校准代理，置信度高的分支多深一层、低的早剪，节点预算花在期望收益最高的地方；相对 EAGLE-1 加速比再提高约二到四成。</p><p><strong>EAGLE-3</strong>：扔掉特征回归，直接预测 token；输入从倒二层换成低、中、高三层特征融合；训练里做 training-time test——把草稿自己的多步输出当后续步输入，让训练分布对齐推理分布。论文报告相对 EAGLE-2 约 1.4 倍延迟加速、单请求峰值约 6.5 倍，细节见本仓库 <a href="/llm/eagle-3">EAGLE-3</a> 一课。</p>',11)),(t(),B(o,null,{default:a(()=>[i(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E7%9B%AE%E6%A0%87%E5%80%92%E4%BA%8C%E5%B1%82%E7%89%B9%E5%BE%81%E5%BA%8F%E5%88%97%22%5D%20--%3E%20D%5B%22%E5%8D%95%E5%B1%82%E8%8D%89%E7%A8%BF%E8%A7%A3%E7%A0%81%E5%99%A8%22%5D%0A%20%20E%5B%22%E9%94%99%E5%BC%80%E4%B8%80%E6%8B%8D%E7%9A%84%20token%20%E5%B5%8C%E5%85%A5%22%5D%20--%3E%20D%0A%20%20D%20--%3E%20NF%5B%22%E4%B8%8B%E4%B8%80%E6%AD%A5%E7%89%B9%E5%BE%81%E9%A2%84%E6%B5%8B%22%5D%0A%20%20NF%20--%3E%20H%5B%22%E5%86%BB%E7%BB%93%20LM%20%E5%A4%B4%22%5D%0A%20%20H%20--%3E%20TD%5B%22%E8%8D%89%E7%A8%BF%20token%20%E5%88%86%E5%B8%83%22%5D%0A%20%20TD%20--%3E%20TREE%5B%22%E6%8C%89%E7%BD%AE%E4%BF%A1%E5%BA%A6%E9%95%BF%E5%8A%A8%E6%80%81%E6%A0%91%22%5D%0A%20%20TREE%20--%3E%20V%5B%22%E7%9B%AE%E6%A0%87%E6%A0%91%E6%B3%A8%E6%84%8F%E5%8A%9B%E6%A0%A1%E9%AA%8C%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[A("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,"这一族成立靠两个机制。其一，特征已经是「差一步到 token」的表示：词头若满秩，倒二层特征与 logits 一一对应，草稿只需学「特征怎么走一步」，任务复杂度远低于从 token 学起的小模型——这是一层草稿解码器就够用的原因，也是词头可以冻结的原因。其二，错开的 token 嵌入把采样变量搬进条件里：草稿 condition 的不再是模糊的分布，而是已实现的那条路径，多步外推才不散。EAGLE-2 的动态树把「接受率随上下文变」这一事实直接写进提议形状：静态树假设 \\(\\alpha\\) 处处相同，动态树按节点估计的边际收益分配预算。EAGLE-3 的 training-time test 则是对复合误差的正面处理：草稿的输入里有它自己的输出，这件事要么写进训练，要么第二步起就在域外。",-1)),E[5]||(E[5]=e("p",null,[e("span",{class:"marginnote"},"EAGLE-2 的置信度代理是校准出来的，不是恒等式：服务端一旦更换接受规则（比如改 typical acceptance），置信度到接受率的映射就变，动态树的生长判据整体失准。改接受规则与换树先验必须一起重测。")],-1)),(t(),B(o,null,{default:a(()=>[i(l,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22%E7%89%B9%E5%BE%81%20h_t%3A%20%E5%AF%B9%E4%B8%8B%E4%B8%80%E8%AF%8D%E5%8F%AA%E6%98%AF%E5%AE%BD%E5%88%86%E5%B8%83%22%5D%20--%3E%20Q%5B%22%E8%8D%89%E7%A8%BF%E5%8F%AA%E7%9C%8B%20h_t%20%E4%BC%9A%E6%80%8E%E6%A0%B7%3F%22%5D%0A%20%20Q%20--%3E%20AMB%5B%22condition%20%E5%9C%A8%E5%88%86%E5%B8%83%E4%B8%8A%2C%20%E7%9B%AE%E6%A0%87%E5%8D%B4%E6%8A%BD%E4%BA%86%E5%85%B7%E4%BD%93%E8%AF%8D%22%5D%0A%20%20AMB%20--%3E%20BAD%5B%22%E6%AD%A7%E4%B9%89%E4%BB%8E%E7%AC%AC%E4%B8%80%E6%AD%A5%E7%B4%AF%E7%A7%AF%2C%20%E5%A4%9A%E6%AD%A5%E5%A4%96%E6%8E%A8%E6%95%A3%E6%9E%B6%22%5D%0A%20%20H%20--%3E%20T%5B%22%E7%9B%AE%E6%A0%87%E5%AE%9E%E9%99%85%E6%8A%BD%E5%87%BA%E7%9A%84%20token%20t%22%5D%0A%20%20T%20--%3E%20FIX%5B%22%E6%8A%8A%20t%20%E7%9A%84%E5%B5%8C%E5%85%A5%E9%94%99%E5%BC%80%E4%B8%80%E6%8B%8D%E5%96%82%E5%9B%9E%E8%8D%89%E7%A8%BF%22%5D%0A%20%20FIX%20--%3E%20COND%5B%22%E8%8D%89%E7%A8%BF%20condition%20%E5%9C%A8%E5%B7%B2%E5%AE%9E%E7%8E%B0%E8%B7%AF%E5%BE%84%E4%B8%8A%22%5D%0A%20%20COND%20--%3E%20GOOD%5B%22%E6%AD%A7%E4%B9%89%E8%A7%A3%E5%BC%80%2C%20%E6%B7%B1%E8%8D%89%E7%A8%BF%E5%8F%AF%E8%A1%8C%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=n('<p><span class="marginnote">术语翻译：training-time test 指训练阶段就模拟推理时的情形——草稿的输入里掺着草稿自己生成的输出。相当于背课文时不只对着标准答案背，还提前练「默写出错后接着往下写」，让模型提前见过自己会犯的错，推理第二步起才不落在没学过的分布外。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>草稿要为目标逐个训练：倒二层挂钩的位置、融合层的索引都是超参，换架构（Norm 位置、词头是否解绑）要重做。闭源目标没有特征接口，这一族整体不可用。加速比数字钉在各自设定上：Vicuna-13B 温度为零的峰值不能抄成所有模型的常数，也不能与独立草稿、Medusa 的表互相乘算——上一课已见过 batch=1 的坑，这里多一个「贪心峰值」的坑。最后分清对象：DeepSeek 预训练期的 <a href="/llm/mtp">MTP</a> 是训练目标与顺序模块，不是 EAGLE 一族的推理插件，两者的草稿供给侧不同源。</p><p><span class="marginnote">常见误区：初学者容易把 EAGLE 的草稿当成一个通用小语言模型，换谁都能用。它实际只为特定目标模型定制——挂在哪一层特征、配哪个词头都是配套设计的，所以开源可改的目标模型能用，只有 API 的闭源模型装不上这一族。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Eagle 一族让草稿在特征层自回归：单层解码器加冻结词头，任务从「学语言」缩成「学特征怎么走一步」。</li><li>错开一拍的 token 嵌入解开 feature uncertainty：草稿 condition 在已实现的采样路径上。</li><li>谱系三代：EAGLE 静态树，EAGLE-2 置信度驱动动态树，EAGLE-3 扔特征回归、融合多层、training-time test。</li><li>动态树的置信度代理依赖校准，接受规则一换就要重测。</li><li>无损声明继承拒绝采样；加速比钉温度、批量与任务，不可跨表乘算。</li><li>出处：Li et al., <em>EAGLE</em>, ICML 2024；<em>EAGLE-2</em>, EMNLP 2024；<em>EAGLE-3</em>, NeurIPS 2025。</li></ul>',6))])}const L=r(d,[["render",m]]);export{k as __pageData,L as default};
